import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import './Prediction.css';

const questions = [
  { key: 'age', question: "Hi! Let's predict your diabetes risk. How old are you?", type: 'number', min: 0, max: 120 },
  { key: 'gender', question: "What is your gender?", type: 'options', options: ['Female', 'Male', 'Other'] },
  { key: 'bmi', question: "What's your BMI (Body Mass Index)?", type: 'number', min: 10, max: 50 },
  { key: 'hbA1c_level', question: "What's your HbA1c Level (%)?", type: 'number', min: 3, max: 15 },
  { key: 'blood_glucose_level', question: "What's your Blood Glucose Level (mg/dL)?", type: 'number', min: 50, max: 300 },
  { key: 'hypertension', question: "Do you have hypertension?", type: 'boolean' },
  { key: 'heart_disease', question: "Do you have heart disease?", type: 'boolean' },
  { key: 'smoking_history', question: "What is your smoking history?", type: 'options', options: ['never', 'former', 'current', 'not current', 'ever'] },
];

function Prediction() {
  const [messages, setMessages] = useState([
    { from: 'bot', text: questions[0].question }
  ]);
  const [currentStep, setCurrentStep] = useState(0);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [answers, setAnswers] = useState({});
  const [prediction, setPrediction] = useState(null);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const addMessage = (from, text) => {
    setMessages(prev => [...prev, { from, text }]);
  };

  const normalizeInput = (value, currentQuestion) => {
    if (!value) return null;
    const val = value.toLowerCase().trim();
    if (currentQuestion.type === 'boolean') {
      if (val.includes('no')) return 0;
      if (val.includes('yes')) return 1;
    }
    if (currentQuestion.type === 'number') {
      const num = parseFloat(val.match(/\d+(\.\d+)?/)?.[0]);
      if (!isNaN(num) && num >= currentQuestion.min && num <= currentQuestion.max) return num;
    }
    if (currentQuestion.type === 'options') {
      const match = currentQuestion.options.find(opt => val.includes(opt.toLowerCase()));
      if (match) return match;
    }
    return null;
  };

  const handleUserInput = async () => {
    const normalized = normalizeInput(inputValue, questions[currentStep]);
    if (normalized === null) {
      alert('Please enter a valid answer.');
      return;
    }
    addMessage('user', inputValue);

    const currentQuestion = questions[currentStep];
    const newAnswers = { ...answers, [currentQuestion.key]: normalized };
    setAnswers(newAnswers);
    setInputValue('');

    if (currentStep + 1 < questions.length) {
      setTimeout(() => {
        addMessage('bot', questions[currentStep + 1].question);
        setCurrentStep(currentStep + 1);
      }, 800);
    } else {
      setIsLoading(true);
      setTimeout(async () => {
        try {
          const response = await axios.post('http://localhost:8000/predict', newAnswers, {
            headers: { 'Content-Type': 'application/json' },
          });
          const pred = response.data;
          addMessage('bot', `Prediction Result: ${pred.interpretation} with probability ${(pred.probability * 100).toFixed(1)}%.`);
          addMessage('bot', pred.prediction
            ? "We recommend consulting with a healthcare professional for further evaluation."
            : "Maintain healthy habits to keep your risk low.");
          setPrediction(pred);
        } catch (err) {
          addMessage('bot', "Sorry, prediction failed. Please try again later.");
        } finally {
          setIsLoading(false);
        }
      }, 1000);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !isLoading) {
      handleUserInput();
    }
  };

  const renderInput = () => {
    const currentQuestion = questions[currentStep];
    if (currentQuestion.type === 'options') {
      return (
        <select
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          disabled={isLoading}
        >
          <option value="">-- Select --</option>
          {currentQuestion.options.map(opt => (
            <option key={opt} value={opt}>{opt}</option>
          ))}
        </select>
      );
    }
    return (
      <input
        type="text"
        placeholder="Type your answer..."
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        onKeyDown={handleKeyPress}
        disabled={isLoading}
        autoFocus
      />
    );
  };

  return (
    <div className="chatbot-container">
      <h2>Diabetes Risk Prediction Chatbot</h2>
      <div className="chat-window">
        {messages.map((msg, i) => (
          <div key={i} className={`chat-message ${msg.from}`}>
            <div className="message-bubble">{msg.text}</div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {!prediction && (
        <div className="chat-input">
          {renderInput()}
          <button onClick={handleUserInput} disabled={isLoading || inputValue.trim() === ''}>
            {isLoading ? '...' : 'Send'}
          </button>
        </div>
      )}

      {prediction && (
        <button className="restart-btn" onClick={() => {
          setMessages([{ from: 'bot', text: questions[0].question }]);
          setCurrentStep(0);
          setAnswers({});
          setPrediction(null);
          setInputValue('');
        }}>
          Start Over
        </button>
      )}
    </div>
  );
}

export default Prediction;
